  barScope(into, opts) {
    const o = opts || {};
    const wrap = into.createDiv({ cls: "ws-scopebar" });
    const crumbs = wrap.createDiv({ cls: "ws-scopecrumbs" });
    const quiet = !!o.noSearch;
    const input = quiet ? null : wrap.createEl("input", { cls: "ws-export-text ws-scopeinput" });
    if (input) {
      input.type = "text";
      input.placeholder = o.placeholder || "Search for a folder or a note…";
    }
    const hits = quiet ? null : wrap.createDiv({ cls: "ws-export-hits ws-scopehits" });
    if (quiet)
      wrap.addClass("is-quiet");
    const norm = (p2) => !p2 || p2 === "/" ? "" : String(p2).replace(/^\/+|\/+$/g, "");
    let at = norm(o.current || "");
    let searching = false;
    const take = (path, kind) => {
      at = norm(path);
      searching = false;
      if (input)
        input.value = "";
      if (hits)
        hits.textContent = "";
      paint();
      if (o.onPick)
        o.onPick(at, kind || "folder");
    };
    const paintHits = () => {
      if (!input || !hits)
        return;
      hits.textContent = "";
      const found = this.scopeFinderMatches(input.value, 10, o.foldersOnly);
      if (!found.length) {
        hits.createDiv({ cls: "ws-export-nohit", text: "Nothing by that name." });
        return;
      }
      for (const h of found) {
        const r = hits.createDiv({ cls: "ws-export-hit" });
        r.createSpan({
          cls: "ws-export-hitkind",
          text: h.vault ? "vault" : h.kind === "folder" ? "folder" : "note"
        });
        r.createSpan({
          cls: "ws-export-hitpath",
          text: h.vault ? this.vaultWhole() : h.path
        });
        const n = this.scopeNoteCount(h.path, h.kind);
        if (h.kind === "folder") {
          r.createSpan({
            cls: "ws-scopecount",
            text: n + (n === 1 ? " note" : " notes")
          });
        }
        r.addEventListener("mousedown", (ev) => {
          ev.preventDefault();
          take(h.path, h.kind);
        });
      }
    };
    const openSearch = (seed) => {
      searching = true;
      paint();
      if (!input)
        return;
      input.value = seed || "";
      input.focus();
      paintHits();
    };
    const paint = () => {
      wrap.toggleClass("is-searching", searching);
      crumbs.textContent = "";
      const label = crumbs.createSpan({ cls: "ws-scopename" });
      label.setText(at ? at.replace(/\.md$/i, "") : this.vaultWhole());
      label.title = at || this.vaultWhole();
      if (quiet)
        return;
      const find = crumbs.createEl("button", { cls: "ws-crumb ws-crumb-find" });
      find.title = "Search for a folder or a note";
      try {
        if (import_obsidian22.setIcon)
          (0, import_obsidian22.setIcon)(find, "search");
      } catch {
        find.setText("⌕");
      }
      find.addEventListener("click", () => openSearch(""));
    };
    if (input) {
      input.addEventListener("input", paintHits);
      input.addEventListener("focus", () => {
        searching = true;
        wrap.addClass("is-searching");
        paintHits();
      });
      input.addEventListener("keydown", (ev) => {
        if (ev.key === "Escape") {
          searching = false;
          input.value = "";
          if (hits)
            hits.textContent = "";
          paint();
        }
      });
      input.addEventListener("blur", () => {
        window.setTimeout(() => {
          if (hits)
            hits.textContent = "";
          if (!input.value.trim()) {
            searching = false;
            paint();
          }
        }, 140);
      });
    }
    paint();
    return { el: wrap, set: (p2) => {
      at = norm(p2);
      paint();
    }, at: () => at };
  },
